mapper.update:
update personal_workspace_relocations
set status = 'TRANSFERRING', snapshot_sha256 = #{snapshotSha256},
    archive_size_bytes = #{archiveSizeBytes}, updated_at = #{now}
where relocation_id = #{relocationId}
  and status = 'EXPORTING'
  and lease_owner = #{leaseOwner}
  and lease_until > #{now}

update personal_workspace_relocations
set status = 'APPLYING', updated_at = #{now}
where relocation_id = #{relocationId}
  and status = 'TRANSFERRING'
  and snapshot_sha256 = #{snapshotSha256}
  and archive_size_bytes = #{archiveSizeBytes}
  and lease_until > #{now}

update workspaces
set root_path = #{targetWorkspaceRootPath}, linux_server_id = #{targetLinuxServerId},
    trace_id = #{traceId}, updated_at = #{now}
where workspace_id = (
    select runtime_workspace_id from personal_workspace_relocations where relocation_id = #{relocationId}
)
  and linux_server_id = #{sourceLinuxServerId}
  and status = 'ACTIVE'

update personal_workspaces
set repo_root_path = #{targetRepoRootPath}, workspace_root_path = #{targetWorkspaceRootPath},
    base_commit = #{baseCommit}, updated_at = #{now}
where personal_workspace_id = (
    select personal_workspace_id from personal_workspace_relocations where relocation_id = #{relocationId}
)
  and status = 'ACTIVE'

update personal_workspace_relocations
set status = 'CLEANUP_PENDING', target_applied_at = #{now}, updated_at = #{now}
where relocation_id = #{relocationId} and status = 'APPLYING'

update personal_workspace_relocations
set status = case when status = 'CLEANUP_PENDING' then 'CLEANUP_PENDING' else 'RETRY_WAIT' end,
    attempt_count = #{attemptCount}, next_retry_at = #{nextRetryAt},
    safe_error_code = #{safeErrorCode}, safe_error_message = #{safeErrorMessage},
    lease_owner = null, lease_until = null, updated_at = #{now}
where relocation_id = #{relocationId}
  and lease_owner = #{leaseOwner}
  and status in ('EXPORTING', 'TRANSFERRING', 'APPLYING', 'CLEANUP_PENDING')

update personal_workspace_relocations
set status = 'SUCCEEDED', lease_owner = null, lease_until = null,
    safe_error_code = null, safe_error_message = null,
    completed_at = #{now}, updated_at = #{now}
where relocation_id = #{relocationId}
  and status = 'CLEANUP_PENDING'
  and lease_owner = #{leaseOwner}
